import { useCompanyList } from '../companies/companyQueries';
import { useContactList } from '../contacts/contactQueries';

const STAGE_OPTIONS = [
  { value: 'lead', label: 'Lead' },
  { value: 'qualified', label: 'Qualified' },
  { value: 'proposal', label: 'Proposal' },
  { value: 'negotiation', label: 'Negotiation' },
  { value: 'closed_won', label: 'Closed Won' },
  { value: 'closed_lost', label: 'Closed Lost' },
];

function formatDateTimeLocal(value) {
  if (!value) {
    return '';
  }

  const date = new Date(value);
  const timezoneOffset = date.getTimezoneOffset() * 60000;
  return new Date(date.getTime() - timezoneOffset).toISOString().slice(0, 16);
}

function normalizeInitialValues(initialValues) {
  const contactLinks = Array.isArray(initialValues?.contacts)
    ? initialValues.contacts.map((contact) => ({
        contactId: contact.id,
        role: contact.role ?? '',
      }))
    : initialValues?.contactId
      ? [{ contactId: initialValues.contactId, role: '' }]
      : [];

  const fallbackPrimaryContactId =
    initialValues?.primaryContactId ??
    initialValues?.contacts?.find((contact) => contact.primary)?.id ??
    initialValues?.contactId ??
    '';

  return {
    name: initialValues?.name ?? '',
    value: initialValues?.value ?? '',
    stage: initialValues?.stage ?? 'lead',
    companyId: initialValues?.companyId ?? '',
    contactLinks,
    primaryContactId: fallbackPrimaryContactId,
    expectedCloseDate: formatDateTimeLocal(initialValues?.expectedCloseDate),
  };
}

function validate(values) {
  const errors = {};

  if (!values.name.trim()) {
    errors.name = 'Name is required.';
  }

  if (values.value === '' || values.value === null || values.value === undefined) {
    errors.value = 'Value is required.';
  } else if (Number(values.value) < 0) {
    errors.value = 'Value must be non-negative.';
  }

  if (!values.companyId) {
    errors.companyId = 'Company is required.';
  }

  if (
    values.primaryContactId &&
    !values.contactLinks.some((link) => link.contactId === values.primaryContactId)
  ) {
    errors.primaryContactId = 'Primary contact must be in linked contacts.';
  }

  return errors;
}

export function DealFormDialog({
  open,
  mode,
  initialValues,
  onClose,
  onSubmit,
  isPending,
}) {
  const [values, setValues] = useState(normalizeInitialValues(initialValues));
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});

  useEffect(() => {
    if (open) {
      setValues(normalizeInitialValues(initialValues));
      setErrors({});
      setTouched({});
    }
  }, [open, initialValues]);

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList(
    values.companyId ? { companyId: values.companyId, page: 1, pageSize: 100 } : { page: 1, pageSize: 100 },
  );

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = contactsQuery.data?.items ?? [];

  const companyValue =
    companyOptions.find((option) => option.id === values.companyId) ?? null;

  const selectedContacts = useMemo(() => {
    const optionMap = new Map(contactOptions.map((contact) => [contact.id, contact]));
    return values.contactLinks
      .map((link) => optionMap.get(link.contactId))
      .filter(Boolean);
  }, [contactOptions, values.contactLinks]);

  useEffect(() => {
    if (!values.companyId) {
      setValues((current) => ({
        ...current,
        contactLinks: [],
        primaryContactId: '',
      }));
      return;
    }

    const validContactIds = new Set(contactOptions.map((contact) => contact.id));
    setValues((current) => {
      const nextLinks = current.contactLinks.filter((link) => validContactIds.has(link.contactId));
      const hasPrimary = nextLinks.some((link) => link.contactId === current.primaryContactId);
      const nextPrimaryContactId =
        hasPrimary || nextLinks.length === 0
          ? current.primaryContactId
          : nextLinks[0].contactId;

      return {
        ...current,
        contactLinks: nextLinks,
        primaryContactId: nextPrimaryContactId,
      };
    });
  }, [values.companyId, contactOptions]);

  useEffect(() => {
    setValues((current) => {
      if (current.contactLinks.length === 1 && !current.primaryContactId) {
        return {
          ...current,
          primaryContactId: current.contactLinks[0].contactId,
        };
      }

      if (
        current.primaryContactId &&
        !current.contactLinks.some((link) => link.contactId === current.primaryContactId)
      ) {
        return {
          ...current,
          primaryContactId: current.contactLinks[0]?.contactId ?? '',
        };
      }

      return current;
    });
  }, [values.contactLinks]);

  const handleFieldChange = (field) => (event) => {
    const fieldValue = event.target.value;
    setValues((current) => ({ ...current, [field]: fieldValue }));

    if (errors[field]) {
      setErrors((current) => {
        const next = { ...current };
        delete next[field];
        return next;
      });
    }
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
    setErrors(validate(values));
  };

  const handleContactSelectionChange = (_, selected) => {
    const selectedIds = new Set(selected.map((item) => item.id));

    setValues((current) => {
      const roleById = new Map(current.contactLinks.map((link) => [link.contactId, link.role]));
      const nextContactLinks = selected.map((contact) => ({
        contactId: contact.id,
        role: roleById.get(contact.id) ?? '',
      }));

      const nextPrimaryContactId =
        selectedIds.has(current.primaryContactId)
          ? current.primaryContactId
          : nextContactLinks.length === 1
            ? nextContactLinks[0].contactId
            : '';

      return {
        ...current,
        contactLinks: nextContactLinks,
        primaryContactId: nextPrimaryContactId,
      };
    });
  };

  const handleContactRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((link) =>
        link.contactId === contactId ? { ...link, role } : link,
      ),
    }));
  };

  const handleSubmit = async (event) => {
    event?.preventDefault();

    const nextErrors = validate(values);
    setErrors(nextErrors);
    setTouched({
      name: true,
      value: true,
      companyId: true,
      primaryContactId: true,
    });

    if (Object.keys(nextErrors).length > 0) {
      return;
    }

    const payload = {
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage || undefined,
      companyId: values.companyId,
      contactLinks: values.contactLinks.map((link) => ({
        contactId: link.contactId,
        role: link.role?.trim() || null,
      })),
      primaryContactId: values.primaryContactId || null,
      expectedCloseDate: values.expectedCloseDate
        ? new Date(values.expectedCloseDate).toISOString()
        : null,
    };

    await onSubmit(payload);
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent className="!p-5">
        <Stack direction="column" spacing={2} component="form" onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            required
            fullWidth
            label="Name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleFieldChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Value"
              type="number"
              value={values.value}
              onBlur={handleBlur('value')}
              onChange={handleFieldChange('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
              inputProps={{ min: 0, step: '0.01' }}
            />

            <TextField
              select
              fullWidth
              label="Stage"
              value={values.stage}
              onChange={handleFieldChange('stage')}
            >
              {STAGE_OPTIONS.map((option) => (
                <MenuItem key={option.value} value={option.value}>
                  {option.label}
                </MenuItem>
              ))}
            </TextField>
          </Stack>

          <Autocomplete
            options={companyOptions}
            loading={companiesQuery.isLoading}
            value={companyValue}
            onChange={(_, selectedCompany) => {
              setValues((current) => ({
                ...current,
                companyId: selectedCompany?.id ?? '',
                contactLinks: [],
                primaryContactId: '',
              }));
              setTouched((current) => ({ ...current, companyId: true }));
            }}
            getOptionLabel={(option) => option?.name ?? ''}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
import Box from '@mui/material/Box';
