export const DEAL_STAGES = [
  'lead',
  'qualified',
  'active',
  'negotiation',
  'closed_won',
  'closed_lost',
];

export const DEAL_STAGE_LABELS = {
  lead: 'Lead',
  qualified: 'Qualified',
  active: 'Active',
  negotiation: 'Negotiation',
  closed_won: 'Closed Won',
  closed_lost: 'Closed Lost',
};

export const DEAL_STAGE_COLORS = {
  lead: 'default',
  qualified: 'info',
  active: 'warning',
  negotiation: 'secondary',
  closed_won: 'success',
  closed_lost: 'error',
};

export const DEAL_CREATE_STAGE_OPTIONS = [
  { value: 'lead', label: DEAL_STAGE_LABELS.lead },
  { value: 'qualified', label: DEAL_STAGE_LABELS.qualified },
];

export const DEAL_FILTER_STAGE_OPTIONS = DEAL_STAGES.map((stage) => ({
  value: stage,
  label: DEAL_STAGE_LABELS[stage],
}));

export const DEAL_STAGE_TRANSITIONS = {
  lead: ['qualified', 'closed_lost'],
  qualified: ['active', 'closed_lost'],
  active: ['negotiation', 'closed_lost'],
  negotiation: ['closed_won', 'closed_lost'],
  closed_won: [],
  closed_lost: ['lead'],
};

export function getEditStageTransitionOptions({
  currentStage,
  hasLinkedContacts,
}) {
  const allowedTargets = DEAL_STAGE_TRANSITIONS[currentStage] ?? [];

  return allowedTargets
    .filter((stage) => stage "'!== '"'active' || hasLinkedContacts)
    .map((stage) => ({
      value: stage,
      label: DEAL_STAGE_LABELS[stage] ?? stage,
    }));
}

export function formatDealStageLabel(stage) {
  return DEAL_STAGE_LABELS[stage] ?? '—';
}

export function getDealStageColor(stage) {
  return DEAL_STAGE_COLORS[stage] ?? 'default';
}
EOF"

